/**
 * Small, deterministic telemetry-cost experiment. This uses only the existing explain(Level) API, so exactly this
 * source can run against the base revision. Both arms drain rows; VALUES performs lexical work in the query itself. The
 * telemetry arm includes collection and explanation-model construction, excluding JSON/HTML rendering. Single-fork
 * defaults are exploratory measurements, not a statistical claim about production workloads.
 */
@State(Scope.Thread)
@Threads(1)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Fork(value = 1, jvmArgs = { "-Xms1G", "-Xmx1G" })
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
public class LmdbTelemetryOverheadBenchmark {
	private static final String NS = "urn:rdf4j:telemetry-overhead:";
	private static final int FANOUT = 4;
	private static final Map<String, String> SETTINGS = Map.of(
			"rdf4j.lmdb.nativeQueryEngine.enabled", "true",
			"rdf4j.lmdb.parallel.enabled", "false",
			"rdf4j.lmdb.janinoCodegen.enabled", "true",
			"rdf4j.lmdb.janinoCodegen.synchronous", "true",
			"rdf4j.lmdb.janinoCodegen.thresholdRows", "0");

	@Param({ "COUNT", "FANOUT", "VALUES" })
	public String queryShape;
	@Param({ "evaluate", "telemetry" })
	public String mode;
	@Param({ "10000" })
	public int roots;

	private final Map<String, String> previousProperties = new LinkedHashMap<>();
	private File directory;
	private SailRepository repository;
	private SailRepositoryConnection connection;
	private TupleQuery query;
	private long expectedRows;

	@Setup(Level.Trial)
	public void setUp() throws Exception {
		if (roots <= 0 || roots > 1_000_000)
			throw new IllegalArgumentException("roots must be within 1..1000000");
		if (!mode.equals("evaluate") && !mode.equals("telemetry"))
			throw new IllegalArgumentException("unknown mode");
		try {
			SETTINGS.forEach((name, value) -> {
				previousProperties.put(name, System.getProperty(name));
				System.setProperty(name, value);
			});
			directory = Files.createTempDirectory("rdf4j-telemetry-overhead-").toFile();
			LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
					.setNativeEvaluationEnabled(true)
					.setDirectAdjacencyEnabled(true)
					.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
					.setDirectAdjacencyMaxBytes(256L << 20));
			repository = new SailRepository(store);
			connection = repository.getConnection();
			load();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			if (!store.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS))
				throw new IllegalStateException("adjacency not ready");
			query = connection.prepareTupleQuery(queryText());
			expectedRows = queryShape.equals("COUNT") ? 1 : queryShape.equals("FANOUT") ? (long) roots * FANOUT : roots;
			verifySemantics();
			// Populate all applicable immutable shape caches before JMH's own warmup. Identical in both arms.
			Explanation explanation = null;
			for (int i = 0; i < 4; i++) {
				drain(null);
				explanation = query.explain(Explanation.Level.Telemetry);
			}
			Set<String> paths = new LinkedHashSet<>();
			collectPaths(explanation.toGenericPlanNode(), paths);
			if (paths.isEmpty())
				throw new IllegalStateException("No native execution route was observed");
			System.out.println("telemetry-overhead fixture shape=" + queryShape + ", roots=" + roots
					+ ", expectedRows=" + expectedRows + ", nativePaths=" + paths);
		} catch (Exception | Error failure) {
			try {
				tearDown();
			} catch (Exception | Error cleanup) {
				failure.addSuppressed(cleanup);
			}
			throw failure;
		}
	}

	private void load() {
		var values = connection.getValueFactory();
		var edge = values.createIRI(NS + "edge");
		var tag = values.createIRI(NS + "tag");
		var label = values.createIRI(NS + "label");
		connection.begin();
		for (int lane = 0; lane < FANOUT; lane++)
			connection.add(values.createIRI(NS + "target/" + lane), tag, values.createLiteral(lane));
		for (int i = 0; i < roots; i++) {
			var subject = values.createIRI(NS + "row/" + i);
			connection.add(subject, label, values.createLiteral(label(i)));
			for (int lane = 0; lane < FANOUT; lane++)
				connection.add(subject, edge, values.createIRI(NS + "target/" + lane));
		}
		connection.commit();
	}

	private String queryText() {
		return switch (queryShape) {
		case "COUNT" -> "SELECT (COUNT(*) AS ?n) WHERE { ?s <" + NS + "edge> ?m }";
		case "FANOUT" -> "SELECT ?s ?m ?tag WHERE { ?s <" + NS + "edge> ?m . ?m <" + NS + "tag> ?tag }";
		case "VALUES" -> "SELECT (LCASE(CONCAT(?label, ?label)) AS ?rendered) WHERE { ?s <" + NS + "label> ?label }";
		default -> throw new IllegalArgumentException("unknown queryShape " + queryShape);
		};
	}

	private static String label(int row) {
		return "PAYLOAD-" + row + "-0123456789ABCDEF-0123456789ABCDEF";
	}

	private void verifySemantics() {
		long rows = 0;
		long checksum = 0;
		try (var result = query.evaluate()) {
			while (result.hasNext()) {
				var row = result.next();
				rows++;
				if (queryShape.equals("COUNT"))
					checksum += ((Literal) row.getValue("n")).longValue();
				else if (queryShape.equals("FANOUT"))
					checksum += ((Literal) row.getValue("tag")).longValue();
				else
					checksum += row.getValue("rendered").stringValue().hashCode();
			}
		}
		long expectedChecksum = queryShape.equals("COUNT") ? (long) roots * FANOUT
				: (long) roots * FANOUT * (FANOUT - 1) / 2;
		if (queryShape.equals("VALUES")) {
			expectedChecksum = 0;
			for (int i = 0; i < roots; i++)
				expectedChecksum += (label(i) + label(i)).toLowerCase(Locale.ROOT).hashCode();
		}
		if (rows != expectedRows || checksum != expectedChecksum)
			throw new IllegalStateException("fixture semantic mismatch");
	}

	@Benchmark
	public void runQuery(Blackhole blackhole) {
		if (mode.equals("telemetry"))
			blackhole.consume(query.explain(Explanation.Level.Telemetry));
		else
			drain(blackhole);
	}

	private void drain(Blackhole blackhole) {
		long rows = 0;
		try (var result = query.evaluate()) {
			while (result.hasNext()) {
				var row = result.next();
				if (blackhole != null)
					blackhole.consume(row);
				rows++;
			}
		}
		if (rows != expectedRows)
			throw new IllegalStateException("row count changed during benchmark");
	}

	private static void collectPaths(GenericPlanNode node, Set<String> paths) {
		Map<String, String> metrics = node.getStringMetricsActual();
		String path = metrics == null ? null : metrics.get("nativeExecutionPath");
		if (path != null)
			paths.add(path);
		if (node.getPlans() != null)
			for (GenericPlanNode child : node.getPlans())
				collectPaths(child, paths);
	}

	@TearDown(Level.Trial)
	public void tearDown() throws Exception {
		try {
			if (connection != null) {
				connection.close();
				connection = null;
			}
		} finally {
			try {
				if (repository != null) {
					repository.shutDown();
					repository = null;
				}
			} finally {
				try {
					if (directory != null)
						FileUtil.deleteDir(directory);
				} finally {
					previousProperties.forEach((name, value) -> {
						if (value == null)
							System.clearProperty(name);
						else
							System.setProperty(name, value);
					});
					previousProperties.clear();
				}
			}
		}
	}
}
